import os
from typing import Any, Dict, Optional

import requests


class OAuthCallbackError(Exception):
    pass


class TokenExchangeError(Exception):
    pass


class Auth0FederatedLoginHandler:
    AUTH0_TOKEN_URL_TEMPLATE = "https://{domain}/oauth/token"

    def __init__(
        self,
        domain: Optional[str] = None,
        client_id: Optional[str] = None,
        client_secret: Optional[str] = None,
        redirect_uri: Optional[str] = None,
        session_store: Optional[Dict[str, Any]] = None,
        timeout: int = 15,
    ) -> None:
        self.domain = domain or os.environ["AUTH0_DOMAIN"]
        self.client_id = client_id or os.environ["AUTH0_CLIENT_ID"]
        self.client_secret = client_secret or os.environ["AUTH0_CLIENT_SECRET"]
        self.redirect_uri = redirect_uri or os.environ["AUTH0_REDIRECT_URI"]
        self.session_store = session_store if session_store is not None else {}
        self.timeout = timeout

    def handle_callback(self, query_params: Dict[str, str]) -> Dict[str, Any]:
        error = query_params.get("error")
        if error:
            description = query_params.get("error_description", "Authorization server returned an error.")
            raise OAuthCallbackError(f"{error}: {description}")

        code = query_params.get("code")
        state = query_params.get("state")
        if not code:
            raise OAuthCallbackError("Missing authorization code.")
        if not state:
            raise OAuthCallbackError("Missing state parameter.")

        expected_state = self.session_store.get("oauth_state")
        if not expected_state:
            raise OAuthCallbackError("Missing expected state in session.")
        if state != expected_state:
            raise OAuthCallbackError("Invalid state parameter.")

        return self.exchange_code_for_tokens(code)

    def exchange_code_for_tokens(self, code: str) -> Dict[str, Any]:
        url = self.AUTH0_TOKEN_URL_TEMPLATE.format(domain=self.domain)
        payload = {
            "grant_type": "authorization_code",
            "client_id": self.client_id,
            "client_secret": self.client_secret,
            "code": code,
            "redirect_uri": self.redirect_uri,
        }
        headers = {"Content-Type": "application/json"}

        response = requests.post(url, json=payload, headers=headers, timeout=self.timeout)

        try:
            data = response.json()
        except ValueError as exc:
            raise TokenExchangeError(f"Invalid JSON response from Auth0: {response.text}") from exc

        if not response.ok:
            message = data.get("error_description") or data.get("error") or response.text
            raise TokenExchangeError(f"Auth0 token exchange failed: {message}")

        normalized = {
            "access_token": data.get("access_token"),
            "id_token": data.get("id_token"),
            "refresh_token": data.get("refresh_token"),
            "token_type": data.get("token_type"),
            "expires_in": data.get("expires_in"),
            "scope": data.get("scope"),
            "raw": data,
        }

        if not normalized["access_token"]:
            raise TokenExchangeError("Auth0 response did not include an access_token.")

        return normalized
